from pathlib import Path
import shutil
import time
source = Path('/tmp/casa_bootstrap_tests.tTXJuF')
target = Path('/tmp/casa-682')
# Copy completed stages only after the next compilation has begun writing assembly.
while source.exists():
    for stage, next_stage in [('fp_stage1', 'fp_stage2'), ('fp_stage2', 'fp_stage3')]:
        if (source / (next_stage + '.s')).exists() and not (target / stage).exists():
            shutil.copy2(source / stage, target / stage)
            if (source / (stage + '.s')).exists():
                shutil.copy2(source / (stage + '.s'), target / (stage + '.s'))
    if (source / 'fp_stage3.o').exists():
        shutil.copy2(source / 'fp_stage3.s', target / 'fp_stage3.s')
    time.sleep(0.01)
print('Captured', [p.name for p in target.glob('fp_*')])
